/* Buildless and deliberately usable from file:// as well as a static host. */
(function(){
 'use strict';
 const M=window.Y6Model,L=window.Y6Lesson,app=document.getElementById('app'),viewer=document.getElementById('viewer');
 let state=M.fresh(),welcome=true,lastWelcome=true,activeExt=0,hint='',storageOK=true,workTab=null,toastTimer;
 try{const saved=localStorage.getItem(M.KEY);if(saved)state=M.sanitise(JSON.parse(saved));}catch(e){storageOK=false;}
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const teacher=()=>state.profile.name.trim().toLowerCase()==='teacher';
 const t=(a)=>{if(typeof a==='string')return esc(a);const i=state.lang==='zh'?1:state.lang==='ko'?2:0;return esc(a[0])+(i&&a[i]?`<span class="translation" lang="${i===1?'zh-Hans':'ko'}">${esc(a[i])}</span>`:'');};
 const plain=a=>Array.isArray(a)?a[0]:a;
 const btn=(label,action,cls='',extra='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${t(label)}</button>`;
 const pill=label=>`<span class="tag">${t(label)}</span>`;
 const goalKeys=['knowledge','skills','understanding'];
 const pitstopIndex=()=>L.cards.findIndex(c=>c.id==='pitstop');
 function sectionFor(c){const key=({now:'starter',mission:'starter',learning:'learning',model:'main1',main1:'main1',main2:'main2',pit:'pit',plenary:'plenary',exit:'plenary',save:'save',submit:'save',finish:'save'})[c.stage];return L.sections.find(s=>s.key===key);}
 function learningGoal(c){
  const g=L.learningGoals[c.goal],answer=state.answers['goal_'+c.goal],valid=L.learningResponses[answer];
  return `<div class="goal-check"><section class="goal-highlight" aria-labelledby="learningGoalText"><h3 id="learningGoalText">${t(g.goal)}</h3><p id="learningGoalExample">${t(g.example)}</p></section><fieldset class="goal-self-check" aria-describedby="learningGoalText learningGoalExample"><legend>${t(['Read the goal above. How does it feel today?','读一读上面的目标。你现在感觉如何？','위 목표를 읽어요. 지금 어떻게 느껴지나요?'])}</legend><div class="goal-responses">${Object.entries(L.learningResponses).map(([v,label])=>`<button class="choice ${answer===v?'selected':''}" data-simple="goal_${c.goal}" data-value="${v}" aria-pressed="${answer===v}"><span>${t(label)}</span></button>`).join('')}</div></fieldset>${valid?`<div class="feedback goal-next" role="status"><strong>${t(['My next step','我的下一步','나의 다음 단계'])}</strong>${t(g.next[answer])}</div>`:`<p class="footnote">${t(['This is your starting point, not a test. It is OK if this is new.','这是你的起点，不是测验。第一次学习也没关系。','시험이 아니라 시작점을 알아보는 거예요. 처음 배워도 괜찮아요.'])}</p>`}<section class="goal-support" aria-labelledby="schoolLearningVisual"><h3 id="schoolLearningVisual">${t(['Our school learning visual','学校的学习图示','우리 학교 배움 그림'])}</h3>${visual(c.goal+'.png',g.label,'school-poster')}</section></div>`;
 }
 function learningFocus(){
  const hasCheck=goalKeys.some(g=>L.learningResponses[state.answers['goal_'+g]]),suggested=M.suggestedFocus(state),chosen=L.learningGoals[state.answers.learningFocus];
  return `<div class="goal-layout"><div><h3>${t(['My starting point','我的起点','나의 시작점'])}</h3><ul class="goal-summary">${goalKeys.map(k=>`<li><strong>${t(L.learningGoals[k].label)}</strong><span>${t(L.learningResponses[state.answers['goal_'+k]]||['Not chosen yet','尚未选择','아직 고르지 않았어요'])}</span></li>`).join('')}</ul>${hasCheck?`<p class="focus-suggestion">${t(['From your choices, you could focus on','根据你的选择，你可以关注','내 선택을 보면 여기에 집중해도 좋아요:'])} <strong>${t(L.learningGoals[suggested].label)}</strong></p>`:''}<p class="footnote">${t(['You can choose a different goal. All three matter today.','你可以选择别的目标。今天三个目标都重要。','다른 목표를 골라도 돼요. 오늘 세 목표가 모두 중요해요.'])}</p></div><div><p class="question">${t(['Which goal will you work on a little more?','你想在哪个目标上多努力一点？','어떤 목표를 조금 더 연습할까요?'])}</p><div class="goal-responses">${goalKeys.map(k=>`<button class="choice ${state.answers.learningFocus===k?'selected':''}" data-simple="learningFocus" data-value="${k}" aria-pressed="${state.answers.learningFocus===k}"><span><strong>${t(L.learningGoals[k].label)}</strong>${t(L.learningGoals[k].goal)}</span></button>`).join('')}</div></div></div>${chosen?`<div class="feedback" role="status">${t(['Focus chosen. We will come back to this goal after you have coded and tested.','已选择关注点。编程和测试后，我们会再回到这个目标。','집중할 목표를 골랐어요. 코딩하고 시험한 뒤 이 목표를 다시 돌아봐요.'])}</div>`:''}`;
 }
 function focusReminder(){const g=L.learningGoals[state.answers.learningFocus];return g?`<div class="focus-reminder"><strong>${t(['My focus today','我今天的关注点','오늘 집중할 목표'])} · ${t(g.label)}</strong><span>${t(g.goal)}</span></div>`:'';}
 function learningReport(){
  return `<section class="report-section"><h2>${t(['WAGBA · My starting point','WAGBA · 我的起点','WAGBA · 나의 시작점'])}</h2><p class="report-note">${t(['These are pupil self-checks before coding, not test scores.','这些是编程前的学生自我检查，不是测验分数。','코딩 전 학생의 자기 점검이며 시험 점수가 아니에요.'])}</p><table><tr><th>${t(['Goal','目标','목표'])}</th><th>${t(['My starting point','我的起点','나의 시작점'])}</th></tr>${goalKeys.map(k=>`<tr><td><strong>${t(L.learningGoals[k].label)}</strong><br>${t(L.learningGoals[k].goal)}</td><td>${t(L.learningResponses[state.answers['goal_'+k]]||['Not recorded','未记录','기록 없음'])}</td></tr>`).join('')}</table><p>${t(['My focus','我的关注点','집중할 목표'])}: ${L.learningGoals[state.answers.learningFocus]?t(L.learningGoals[state.answers.learningFocus].goal):t(['Not chosen','未选择','고르지 않음'])}</p></section>`;
 }
 function lessonRoute(){
  const current=sectionFor(L.cards[state.card]).key;
  showDialog(`<h2>${t(['Our lesson steps','我们的课程步骤','우리 수업의 단계'])}</h2><ol class="route-list">${L.sections.map(s=>`<li ${s.key===current&&!activeExt?'aria-current="step"':''}><strong>${t(s.label)}</strong><p>${t(s.purpose)}</p>${s.key===current&&!activeExt?pill(['You are here','你在这里','지금 여기예요']):''}</li>`).join('')}</ol><div class="focus-reminder"><strong>${t(['Extension · optional coding challenges','拓展任务 · 可选编程挑战','추가 도전 · 선택 코딩 도전'])}</strong><p>${t(['After Main Task 2, add a symbol, a sequence or a reset. Return to the lesson for your plenary and saving.','主要任务二后，可以增加符号、顺序或重置功能。再返回课程做总结和保存。','주요 활동 2 뒤에 기호, 순서, 초기화를 추가해요. 마무리와 저장을 위해 수업으로 돌아와요.'])}</p></div>`);
 }
 const chooseLabel=['Choose an answer, or use “I need help / skip”.','请选择答案，或使用“需要帮助／跳过”。','답을 고르거나 “도움이 필요해요 / 건너뛰기”를 누르세요.'];
 function persist(){state.updatedAt=new Date().toISOString();try{localStorage.setItem(M.KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;}}
 function toast(a){const el=document.getElementById('toast');el.innerHTML=t(a);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
 function language(){return `<select class="language" aria-label="Language support" data-setting="lang"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="zh" ${state.lang==='zh'?'selected':''}>English + 中文</option><option value="ko" ${state.lang==='ko'?'selected':''}>English + 한국어</option></select>`;}
 function header(){return `<header class="site-header"><button class="brand quiet" data-action="welcome" aria-label="Return to welcome"><span class="brand-mark">Y6</span><span>${t(['Classroom Signals','课堂信号','교실 신호'])}</span></button><div class="header-tools">${!welcome?`<span class="saved-label">${t(storageOK?['Saved on this browser','已保存在此浏览器','이 브라우저에 저장됨']:['Use a backup to keep your work','请下载备份来保存','백업을 받아 작품을 보관하세요'])}</span>`:''}${language()}${!welcome?btn(['Lesson steps','课程步骤','수업 단계'],'route','quiet')+btn(['Help','帮助','도움'],'help','quiet')+btn(['Backup','备份','백업'],'backup','quiet'):''}</div></header>`;}
 function field(key,label,value='',placeholder='',profile=false){return `<label class="field"><span>${t(label)}</span><input type="text" data-${profile?'profile':'text'}="${key}" value="${esc(value)}" maxlength="${profile?80:1000}" placeholder="${esc(placeholder)}" autocomplete="off"></label>`;}
 function check(key,label){return `<label class="check"><input type="checkbox" data-check="${key}" ${state.checks[key]?'checked':''}><span>${t(label)}</span></label>`;}
 function visual(file,alt,cls='concept-image',caption){return `<figure class="lesson-figure"><img class="${cls}" src="assets/${esc(file)}" alt="${esc(plain(alt))}">${caption?`<figcaption>${t(caption)}</figcaption>`:''}</figure>`;}
 function plannedMessages(){return `<div class="message-strip"><strong>${t(['My plan','我的计划','내 계획'])}</strong><p>A · ${esc(state.texts.messageA||plain(L.purposes[state.purpose].A))}<br>B · ${esc(state.texts.messageB||plain(L.purposes[state.purpose].B))}</p></div>`;}
 function scenarioSamples(p,compact=false){return `<div class="signal-samples ${compact?'compact-samples':''}">${['A','B'].map(letter=>{const example=p['example'+letter],caption=example.name.map((name,i)=>['Example: ','示例：','예시: '][i]+name),alt=example.name.map((name,i)=>['Example after button '+letter+': ','按 '+letter+' 后的示例：',letter+' 버튼 뒤 예시: '][i]+name);return `<section class="signal-sample"><div class="signal-heading"><span class="sample-key">${letter}</span><h4>${t(p[letter])}</h4></div>${visual(example.image,alt,'signal-board',caption)}${compact?'':`<p class="signal-when">${t(example.when)}</p>`}</section>`;}).join('')}</div>`;}
 function purposePage(){const p=L.purposes[state.purpose];return `<div class="purpose-switcher" role="group" aria-label="Choose a scenario">${Object.entries(L.purposes).map(([key,purpose])=>`<button class="button ${state.purpose===key?'selected':''}" data-purpose="${key}" aria-pressed="${state.purpose===key}">${state.purpose===key?'<span aria-hidden="true">✓</span>':''}${t(purpose.title)}</button>`).join('')}</div><p class="purpose-context">${t(p.situation)}</p><div class="purpose-preview"><div class="scenario-story">${visual(p.scene,p.sceneAlt,'scenario-illustration')}</div><section class="scenario-displays" aria-label="Example button A and B displays">${scenarioSamples(p)}</section></div><p class="scenario-meaning">${t(p.note)}</p><p class="scenario-next">${t(['These are example pictures. Your board colour may differ; compare the LED pattern. Next, plan your messages, then build and test them in MakeCode.','这些图片是示例。你的板子颜色可能不同，请比较 LED 图案。接下来计划信息，再在 MakeCode 制作并测试。','이 그림은 예시예요. 보드 색이 달라도 LED 무늬를 비교해요. 다음에 메시지를 계획하고 MakeCode에서 만들고 시험해요.'])}</p>`;}
 function hardwareVideo(){
  const v=L.hardware.video;
return `<div class="video-heading"><h3 class="hardware-step-title">${t(v.watch)}</h3><a class="button" href="https://www.youtube.com/watch?v=${esc(v.id)}" target="_blank" rel="noopener noreferrer">${t(['Video not playing? Open it on YouTube ↗','视频不能播放？在 YouTube 打开 ↗','영상이 안 나오나요? YouTube에서 열기 ↗'])}</a></div><div class="video-stage"><div><div class="video-player"><iframe src="https://www.youtube-nocookie.com/embed/${esc(v.id)}?rel=0&amp;cc_load_policy=1&amp;playsinline=1" title="${esc(v.title[0])} — USB cable demonstration" allow="encrypted-media; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><p class="video-credit">${t(v.title)} · ${esc(v.creator)}</p><p class="footnote">${t(['YouTube is a separate service and needs internet access. You can use our picture guide if it is blocked.','YouTube 是独立服务，需要网络。如果被阻止，可以使用我们的图片指南。','YouTube는 별도 서비스이며 인터넷이 필요해요. 차단되면 그림 안내를 사용해도 돼요.'])}</p></div><div class="video-copy"><p class="question">${t(v.spot)}</p><p>${t(v.summary)}</p><p class="video-takeaway">${t(v.limit)}</p><p class="footnote">${t(v.adapter)}</p><p class="footnote">${t(v.caption)}</p><button class="button ${state.answers.hardwareResult==='simulator'?'selected':''}" data-simple="hardwareResult" data-value="simulator" aria-pressed="${state.answers.hardwareResult==='simulator'}">${t(['No board today — I used the simulator','今天没有板子——我使用了模拟器','오늘 보드가 없어요 — 시뮬레이터를 사용했어요'])}</button>${state.answers.hardwareResult==='simulator'?`<p class="feedback" role="status">${t(L.hardware.results.simulator)}</p>`:''}</div></div>`;
 }
 function hardwarePage(){
  const h=L.hardware,n=/^[0-5]$/.test(state.answers.hardwareStep)?Number(state.answers.hardwareStep):0,s=h.steps[n-1],result=h.results[state.answers.hardwareResult];
  if(n===0)return hardwareVideo();
  const stepButton=(i,label,cls='')=>`<button class="button ${cls}" data-simple="hardwareStep" data-value="${i}" aria-pressed="${n===i}">${t(label)}</button>`;
return `<div class="hardware-replay">${stepButton(0,['▶ Watch the cable clip again · 21s','▶ 再看一次线缆视频 · 21 秒','▶ 케이블 영상 다시 보기 · 21초'],'quiet')}</div><div class="hardware-stepper" role="group" aria-label="USB pairing guide steps">${h.steps.map((s,i)=>stepButton(i+1,[['1 · Plug in','1 · 插线','1 · 연결'],['2 · Open menu','2 · 打开菜单','2 · 메뉴'],['3 · Pair','3 · 配对','3 · 연결 선택'],['4 · Choose board','4 · 选择板子','4 · 보드 선택'],['5 · Send & test','5 · 发送和测试','5 · 보내고 시험']][i],n===i+1?'selected':'')).join('')}</div><h3 class="hardware-step-title">${t(s.title.map(x=>n+' · '+x))}</h3><div class="hardware-guide"><div class="hardware-copy">${n===1?`<div class="hardware-ready"><p>${t(h.ready)}</p><button class="button ${state.answers.hardwareResult==='simulator'?'selected':''}" data-simple="hardwareResult" data-value="simulator" aria-pressed="${state.answers.hardwareResult==='simulator'}">${t(['I used the simulator — no board today','我使用了模拟器——今天没有板子','시뮬레이터를 사용했어요 — 오늘 보드가 없어요'])}</button></div>`:''}${result?`<p class="feedback hardware-record" role="status">${t(result)} ${t(['Recorded for your report. You can continue to the Learning Pitstop.','已记入报告。你可以继续前往学习加油站。','보고서에 기록했어요. 배움 점검으로 계속해도 돼요.'])}</p>`:''}${steps(s.lines)}${n===5?plannedMessages():''}<p class="footnote">${t(n===4?['The browser window pictured is an official example. Yours may look different.','图中的浏览器窗口是官方示例，你的窗口可能不同。','그림의 브라우저 창은 공식 예시예요. 내 창은 조금 다를 수 있어요.']:n===5?['Example connected window — this picture does not check your connection. Use the message in your own MakeCode tab.','这是已连接窗口的示例，不代表已检查你的连接。请查看自己 MakeCode 标签页中的信息。','연결 창 예시일 뿐 내 연결을 확인하는 그림은 아니에요. 내 MakeCode 탭의 메시지를 확인해요.']:['These screenshots show MakeCode, not buttons to press in this lesson page. Follow the steps in your own MakeCode tab.','这些截图展示 MakeCode，不是课程网页上的按钮。请在自己的 MakeCode 标签页按步骤操作。','이것은 MakeCode 화면 사진이며 수업 페이지에서 누르는 버튼이 아니에요. 내 MakeCode 탭에서 따라 해요.'])}</p></div><div class="hardware-images">${s.secondaryImage?visual(s.secondaryImage,['First, press Pair in MakeCode.','先在 MakeCode 点击 Pair。','먼저 MakeCode에서 Pair를 눌러요.'],'hardware-dialog'):''}${visual(s.image,s.alt,'hardware-screenshot')}</div></div><nav class="hardware-nav" aria-label="Pairing picture steps">${n>0?stepButton(n-1,['← Previous picture step','← 上一个图片步骤','← 이전 그림 단계']):''}${n<L.hardware.steps.length?stepButton(n+1,['Next picture step →','下一个图片步骤 →','다음 그림 단계 →'],'green'):''}</nav>${n===5?`<fieldset class="hardware-results"><legend>${t(['What did you try today?','今天你尝试了什么？','오늘 무엇을 해 봤나요?'])}</legend>${simpleChoices('hardwareResult',Object.entries(h.results))}<p class="footnote">${t(['These are your own reports, not automatic hardware checks. Needing help is OK.','这是你的自行记录，不是自动硬件检查。需要帮助也没关系。','내가 직접 기록하는 것이며 자동 하드웨어 검사가 아니에요. 도움이 필요해도 괜찮아요.'])}</p></fieldset>`:''}<aside class="hardware-fallback"><h3>${t(['If pairing does not work','如果不能配对','연결이 안 될 때'])}</h3><p>${t(h.fallback)}</p><p class="footnote"><a href="https://makecode.microbit.org/device/usb/webusb" target="_blank" rel="noopener noreferrer">${t(['Official pairing guide ↗','官方配对指南 ↗','공식 연결 안내 ↗'])}</a> · <a href="https://makecode.microbit.org/device/usb" target="_blank" rel="noopener noreferrer">${t(['HEX file transfer guide ↗','HEX 文件传输指南 ↗','HEX 파일 전송 안내 ↗'])}</a></p></aside>`;
 }
 function hardwareReport(){const r=L.hardware.results[state.answers.hardwareResult];return `<section class="report-section"><h2>${t(['Real micro:bit trial','真正的 micro:bit 尝试','실제 micro:bit 시험'])}</h2><p>${t(r||['Not recorded. No hardware test is assumed.','未记录。不代表已进行硬件测试。','기록 없음. 실제 보드를 시험했다고 간주하지 않아요.'])}</p><p class="report-note">${t(['Pupil-reported only. This lesson page cannot pair, download to or inspect a USB board.','仅为学生自行记录。课程网页不能配对、下载到或检查 USB 板子。','학생의 자기 기록이에요. 수업 페이지는 USB 보드 연결, 전송, 검사를 할 수 없어요.'])}</p></section>`;}
 function instruction(c){
  if(c.id==='build'&&L.purposes[state.purpose].buildGuide)c={...c,...L.purposes[state.purpose].buildGuide};
  const response=c.response?`<label class="field response-field"><span>${t(c.response.prompt)}</span><textarea data-text="${c.response.key}" maxlength="1000" aria-describedby="responseFrame">${esc(state.texts[c.response.key]||'')}</textarea></label><p class="response-frame" id="responseFrame">${t(c.response.frame)} ${t(['Use your own language if it helps.','需要时可以用自己的语言。','도움이 된다면 내 언어를 써도 돼요.'])}</p>`:'';
  const prediction=c.showPrediction?`<div class="prediction-note"><strong>${t(['My prediction before pressing B','按 B 前的预测','B를 누르기 전 예상'])}</strong><p>${state.texts.predictionB?esc(state.texts.predictionB):t(['No written prediction yet.','尚未记录预测。','아직 적은 예상이 없어요.'])}</p></div>`:'';
  const copy=`<div class="instruction-copy">${c.practical?makecodeButton():''}${c.showPlan?plannedMessages():''}${prediction}${steps(c.steps||[])}${c.showFilename?`<p class="filename-example"><strong>${t(['Your file name could be','文件名可以是','이런 파일 이름을 써도 돼요'])}</strong><span class="inline-code">${esc(safeName()+'_ClassroomSignal.hex')}</span></p>`:''}${response}${c.check?`<div class="check-list">${check(c.check[0],c.check[1])}</div>`:''}</div>`;
  const picture=c.image?visual(c.image,c.title,c.image.startsWith('code')?'code-image':'annotated-guide',c.caption):'';
  return `<div class="instruction-layout ${c.wide?'wide-guide':''}">${copy}<div class="instruction-visual">${picture}${c.secondaryImage?visual(c.secondaryImage,['Then choose Import File','然后选择 Import File','다음으로 Import File을 골라요'],'annotated-guide'):''}</div></div>`;
 }
 function writtenReport(){
  return `<section class="report-section"><h2>${t(['My predictions and observations','我的预测与观察','나의 예상과 관찰'])}</h2><p class="report-note">${t(['Short written responses are recorded, not automatically marked. Earlier multiple-choice responses are labelled separately.','简短书面回答会被记录，不会自动评分。以前的选择题回答会单独注明。','짧게 쓴 답은 기록되며 자동 채점하지 않아요. 이전 선택형 답은 따로 표시해요.'])}</p>${L.cards.filter(c=>c.response).map(c=>{const response=state.texts[c.response.key],legacy=L.legacyChoices[c.id]||{},old=Object.prototype.hasOwnProperty.call(legacy,state.answers[c.id])?legacy[state.answers[c.id]]:null;return `<h3>${t(c.response.prompt)}</h3><p>${response?.trim()?esc(response):t(['No written response recorded.','未记录书面回答。','기록된 서술형 답이 없어요.'])}</p>${old?`<p class="report-note">${t(['Earlier MCQ response (not a written answer)','以前的选择题回答（不是书面回答）','이전 선택형 답 (서술형 답이 아님)'])}: ${t(old)}</p>`:''}`;}).join('')}</section>`;
 }
 function steps(a){return `<ol class="step-list">${a.map(s=>`<li><span>${t(s)}</span></li>`).join('')}</ol>`;}
 function makecodeButton(){return btn(state.openedMakecode?['Return to my MakeCode work ↗','返回我的 MakeCode 作品 ↗','내 MakeCode 작품으로 돌아가기 ↗']:['Open the MakeCode starter ↗','打开 MakeCode 起始程序 ↗','MakeCode 시작 프로그램 열기 ↗'],'makecode','green large');}
 function codeBanner(){return `<div class="task-banner">${makecodeButton()}<p>${t(['This opens a coding tab. Make your program there, then return here.','这会打开编程标签页。在那里制作程序，然后回到这里。','코딩 탭이 열려요. 그곳에서 프로그램을 만들고 여기로 돌아오세요.'])}</p></div>`;}
 function welcomePage(){const p=state.profile;return `<div class="shell">${header()}<main id="main" class="welcome"><section class="welcome-copy"><p class="eyebrow">${t(['TERM 1 · WEEK 9 · 60 MINUTES','第一学期 · 第九周 · 60 分钟','1학기 · 9주차 · 60분'])}</p><h1>${t(['A small signal.\nA useful idea.','小小信号，实用创意。','작은 신호, 유용한 생각.'])}</h1><p class="lead">${t(['Make a micro:bit signal that helps someone. Read a little, code in MakeCode, then test your idea.','制作一个能帮助别人的 micro:bit 信号。读一点，在 MakeCode 编程，再测试你的想法。','누군가를 돕는 micro:bit 신호를 만들어요. 조금 읽고, MakeCode에서 코딩하고, 생각을 시험해요.'])}</p><div class="welcome-tag">${pill(['MakeCode blocks','MakeCode 积木','MakeCode 블록'])}${pill(['Simulator · no board needed','模拟器 · 无需板子','시뮬레이터 · 보드 불필요'])}</div><div class="mission-hero"><img src="assets/mission.png" alt="One pupil ready to work, another raising a hand for help"></div></section><section class="welcome-form"><p class="eyebrow">${t(['LET’S GET STARTED','开始吧','시작해요'])}</p><h2>${t(['Who is learning today?','今天谁来学习？','오늘 누가 배우나요?'])}</h2>${state.started?`<div class="home-resume"><p>${t(['A saved lesson is here for','已找到以下学生的学习记录','저장된 수업이 있어요:'])} <strong>${esc(p.name)}</strong> · ${esc(p.className)}</p>${btn(['Continue my lesson →','继续我的课程 →','내 수업 계속하기 →'],'resume','green wide')}</div>`:''}<form id="startForm">${field('name',['Your name','你的姓名','이름'],p.name,'e.g. Mina',true)}${field('className',['Your class — type it here','你的班级——请在此输入','반 이름을 직접 적으세요'],p.className,'e.g. 6T',true)}<span class="field-label">${t(['How are you working?','你如何学习？','어떻게 활동하나요?'])}</span><div class="segmented"><label class="radio-tile"><input type="radio" name="mode" value="solo" ${p.mode==='solo'?'checked':''}>${t(['On my own','独立完成','혼자'])}</label><label class="radio-tile"><input type="radio" name="mode" value="pair" ${p.mode==='pair'?'checked':''}>${t(['With a partner','与同伴一起','짝과 함께'])}</label></div>${p.mode==='pair'?field('partner',['Partner’s name — optional','同伴姓名——可选','짝 이름 — 선택'],p.partner,'',true)+`<p class="footnote">${t(['Take turns using the mouse. Either pupil can continue alone at home.','轮流使用鼠标。回家后，任何一人都可以独立继续。','마우스를 번갈아 사용해요. 집에서는 누구나 혼자 이어 할 수 있어요.'])}</p>`:''}<div class="form-actions"><button type="submit" class="button primary wide">${t(state.started?['Start a new record →','开始新的记录 →','새 기록 시작하기 →']:['Start my lesson →','开始我的课程 →','내 수업 시작하기 →'])}</button></div><p id="formError" class="error" hidden></p></form><div class="divider">${t(['continuing from another computer?','从另一台电脑继续？','다른 컴퓨터에서 이어 하나요?'])}</div><label class="button wide" for="restoreFile">↑ ${t(['Load my lesson backup (.json)','载入我的课程备份 (.json)','내 수업 백업 불러오기 (.json)'])}</label><input id="restoreFile" class="file-input" type="file" accept=".json,application/json"><p class="footnote">${t(['Your name and answers stay in this browser. Download a backup to move them. Type teacher as the name to review all pages.','姓名和答案保存在此浏览器。下载备份可以转移记录。姓名输入 teacher 可查看全部页面。','이름과 답은 이 브라우저에 보관돼요. 옮기려면 백업을 받으세요. 이름에 teacher를 입력하면 모든 페이지를 볼 수 있어요.'])}</p></section></main>${credit()}</div>`;}
 function credit(){return `<footer class="footer-credit"><span>${t(['Year 6 Computing · Robotics & Control Systems','六年级计算机 · 机器人与控制系统','6학년 컴퓨팅 · 로봇과 제어 시스템'])}</span><button class="quiet" data-action="credits">${t(['About the visuals','关于这些图片','시각 자료 안내'])}</button></footer>`;}
 function quiz(c){let pic='';if(c.image==='comparison')pic=`<div class="split-result"><div class="result-panel"><h3>${t(['Real board','真实板子','실제 보드'])}</h3><img src="assets/real-microbit.jpg" alt="Official photo of a pupil holding a physical micro:bit"></div><div class="result-panel"><h3>${t(['On-screen model','屏幕模型','화면 속 모델'])}</h3><img src="assets/sim-a.png" alt="MakeCode simulator"></div></div>`;else pic=visual(c.image,['Picture guide: '+c.id,'图片指南','그림 안내'],c.image.startsWith('code')?'code-image':'concept-image');const answer=state.answers[c.id],options=M.quizOptions(state,c);return `${pic}<p class="question">${t(c.question)}</p><div class="choices ${c.options.length===2?'two':''}">${options.map(([value,label],i)=>`<button class="choice ${answer===value?'selected':''}" data-answer="${c.id}" data-value="${value}" aria-pressed="${answer===value}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${t(label)}</span></button>`).join('')}</div>${answer?`<div class="feedback ${answer===c.correct?'':'retry'}" role="status"><strong>${t(answer===c.correct?['That matches the instructions.','这与指令相符。','명령과 맞아요.']:['Look again—you can change your answer.','再看看，你可以修改答案。','다시 보고 답을 바꿔도 돼요.'])}</strong>${t(c.explain)}</div>`:''}`;}
 function body(c){switch(c.type){
 case 'hardware':return hardwarePage();
 case 'instruction':case 'written':return instruction(c);
 case 'quiz':return quiz(c);
 case 'mission':return `<div class="content-grid wide-visual">${visual('mission.png',['Ready to start, or asking for help','准备开始，或寻求帮助','시작할 준비 또는 도움 요청'])}<div><h3>${t(['Your mission','你的任务','나의 미션'])}</h3><p>${t(['Make A mean “ready” and B mean “help”, or choose another useful purpose later.','让 A 表示“准备好了”，B 表示“需要帮助”；稍后也可以选择其他实用用途。','A는 “준비”, B는 “도움”을 뜻하게 해요. 나중에 다른 유용한 목적을 골라도 돼요.'])}</p><p class="small">${t(['This is a control system: a button press controls a light display. It is not a moving robot.','这是一个控制系统：按按钮控制灯光显示，它不是会移动的机器人。','버튼을 누르면 빛 화면을 제어하는 제어 시스템이에요. 움직이는 로봇은 아니에요.'])}</p><p class="small muted">${t(['We agree on what the pictures mean. The micro:bit does not read our feelings.','图案含义由我们约定。micro:bit 不会读懂我们的感受。','그림의 뜻은 우리가 정해요. micro:bit가 기분을 읽는 것은 아니에요.'])}</p></div></div>`;
 case 'learningGoal':return learningGoal(c);
 case 'learningFocus':return learningFocus();
 case 'processDemo':return `<div class="content-grid">${visual('code-a-large.jpg',['A event with its show icon instruction','A 事件和里面的图案指令','A 이벤트와 그 안의 아이콘 명령'],'code-image')}<div>${steps([['Press A: that is the input.','按 A：这是输入。','A를 눌러요. 이것이 입력이에요.'],['The program follows the show icon instruction: that is the process.','程序执行 show icon 指令：这是处理。','프로그램이 show icon 명령을 따라요. 이것이 처리예요.'],['The LED picture appears: that is the output.','LED 图案出现：这是输出。','LED 그림이 나와요. 이것이 출력이에요.']])}<p class="small muted">${t(['The program follows our instructions. It does not choose a picture by itself.','程序按照我们的指令运行，不会自己选择图案。','프로그램은 우리의 명령을 따라요. 스스로 그림을 고르지 않아요.'])}</p></div></div>`;
 case 'launch':return `${codeBanner()}${steps([['Select the green starter button. Wait for MakeCode to open in another tab.','点击绿色起始程序按钮，等待另一个标签页打开 MakeCode。','초록 시작 프로그램 버튼을 누르고 다른 탭에 MakeCode가 열릴 때까지 기다려요.'],['Look for two purple event stacks: on button A pressed and on button B pressed. If asked, choose Edit Code.','找到两个紫色事件积木组：on button A pressed 和 on button B pressed。如果出现提示，选择 Edit Code。','on button A pressed와 on button B pressed 보라색 이벤트 묶음을 찾아요. 물어보면 Edit Code를 골라요.'],['Keep that tab open. Return to this lesson. The next picture will help you find your way around.','保留那个标签页，再回到课程。下一张图片会帮助你认识编辑器。','그 탭을 열어 두고 수업으로 돌아와요. 다음 그림에서 편집기 위치를 알아봐요.']])}<p class="availability">${t(['If the starter link is blocked, download its HEX below. In MakeCode, use Home → Import → Import File to open it. The save section later shows these steps.','如果起始链接被拦截，下载下方 HEX。在 MakeCode 使用 Home → Import → Import File 打开它。后面的保存部分会展示步骤。','시작 링크가 막히면 아래 HEX를 받아요. MakeCode에서 Home → Import → Import File로 열어요. 뒤의 저장 부분에서 방법을 보여 줘요.'])}</p><a class="button" href="assets/Classroom-Signal-Starter.hex" download>${t(['Download the starter HEX file','下载起始 HEX 文件','시작 HEX 파일 받기'])}</a>`;
 case 'purpose':return purposePage();
 case 'plan':{const p=L.purposes[state.purpose];return `<div class="plan-layout"><section class="plan-scenario" aria-labelledby="planScenarioTitle">${visual(p.scene,p.sceneAlt,'plan-scene')}<div><h3 id="planScenarioTitle">${t(p.title)}</h3><p>${t(p.situation)}</p></div></section><section><h3>${t(['Example displays — you may change them','示例显示——你可以改变它们','화면 예시 — 바꿔도 돼요'])}</h3>${scenarioSamples(p,true)}</section></div><div class="plan-fields">${field('messageA',['Button A will mean…','A 按钮表示……','A 버튼의 뜻은…'],state.texts.messageA||'')}${field('messageB',['Button B will mean…','B 按钮表示……','B 버튼의 뜻은…'],state.texts.messageB||'')}</div><p class="plan-note">${t(['Tell a friend or your teacher what your pictures will mean. Working alone? Say your two messages aloud.','告诉同伴或老师你的图案表示什么。独自学习时，可以说出两条信息。','친구나 선생님에게 그림 뜻을 알려요. 혼자라면 두 메시지를 말해 봐요.'])}</p><p class="footnote">${t(['Typing here makes your plan. It does not change your MakeCode blocks yet. Next, you will build and test the program.','在这里输入是在做计划，还不会改变 MakeCode 积木。接下来，你要制作并测试程序。','여기에 적는 것은 계획이에요. 아직 MakeCode 블록이 바뀌지는 않아요. 다음에 프로그램을 만들고 시험해요.'])}</p>`;}
 case 'testCreate':return `<div class="instruction-layout"><div class="instruction-copy">${makecodeButton()}${plannedMessages()}${steps([['Click A in MakeCode. Compare its picture with your A message. Choose its result below.','在 MakeCode 点击 A，把图案与 A 信息比较，再在下面选择结果。','MakeCode에서 A를 클릭해 그림과 A 메시지를 비교하고 아래에 결과를 골라요.'],['Click B and do the same. If a picture is wrong, change the block inside that event and test again.','点击 B 做同样的检查。如果图案不对，修改那个事件里的积木，再次测试。','B도 같은 방법으로 확인해요. 그림이 다르면 그 이벤트 안의 블록을 바꾸고 다시 시험해요.'],['Tell a friend or your teacher what the pictures mean. Working alone? Say the meanings aloud to check your plan.','告诉同伴或老师图案的含义。独自学习时，可以说出含义来检查计划。','짝이나 선생님에게 그림 뜻을 알려요. 혼자라면 뜻을 말하며 계획을 확인해요.']])}</div>${visual('teaching/buttons.svg',['Click A on the left and B on the right in MakeCode','在 MakeCode 点击左边 A 和右边 B','MakeCode에서 왼쪽 A와 오른쪽 B 클릭'],'annotated-guide')}</div><div class="test-results"><h3>${t(['Record your latest test','记录最新测试','최근 시험 기록'])}</h3><div class="test-row"><strong>A</strong><span>${esc(state.texts.messageA)}</span>${testSelect('A')}</div><div class="test-row"><strong>B</strong><span>${esc(state.texts.messageB)}</span>${testSelect('B')}</div>${check('sharedMeaning',['I checked whether someone could understand my signals.','我检查了别人能否理解我的信号。','다른 사람이 내 신호를 이해할 수 있는지 확인했어요.'])}</div><div class="diary"><p class="question">${t(['What happened on your first try?','第一次测试时发生了什么？','처음 시험했을 때 어떻게 되었나요?'])}</p>${simpleChoices('firstTry',[['worked',['Both pictures matched my plan','两个图案都符合计划','두 그림이 계획과 맞았어요']],['changed',['I changed something and tested again','我修改后又测试了一次','수정하고 다시 시험했어요']],['help',['I still need help with a signal','有一个信号仍需要帮助','신호에 아직 도움이 필요해요']]])}${field('debug',['What did you change or check? If it worked first time, what could make the message clearer?','你修改或检查了什么？如果第一次就成功，怎样让信息更清楚？','무엇을 바꾸거나 확인했나요? 처음부터 작동했다면 메시지를 어떻게 더 분명하게 할까요?'],state.texts.debug||'')}</div>`;
 case 'pitstop':return `${focusReminder()}<div class="pitstop-layout">${visual('pitstop-original.png',['Our school Learning Pitstop poster','学校的学习加油站海报','우리 학교 배움 점검 포스터'],'pitstop-poster')}<div><p class="question">${t(['Think about your coding and testing. Which phase fits you now?','想想刚才的编程和测试。你现在处于哪种学习状态？','코딩하고 시험한 것을 생각해요. 지금 어떤 단계인가요?'])}</p><div class="pit-options">${Object.entries(L.phases).map(([k,p])=>`<button class="pit-choice ${state.phase===k?'selected':''}" data-phase="${k}" aria-pressed="${state.phase===k}"><span class="phase-line" style="--phase:${p.color}"></span><span><strong>${t(p.title)}</strong><span class="explain">${t(p.text)}</span></span></button>`).join('')}</div>${state.phase?`<div class="feedback"><strong>${t(['Your next step','你的下一步','다음 단계'])}</strong>${t(L.phases[state.phase].next)}</div>`:''}</div></div>${field('phaseReason',['What in your program helped you choose? You may explain aloud instead.','程序中的什么帮助你做出选择？也可以口头解释。','프로그램의 어떤 점을 보고 골랐나요? 말로 설명해도 돼요.'],state.texts.phaseReason||'')}<p class="footnote">${t(['Ready for more coding? Try an extension, then return for the plenary.','准备继续编程？试试拓展挑战，然后回来做总结。','코딩을 더 해 볼까요? 추가 도전 뒤 마무리로 돌아와요.'])}</p>${btn(['Try an extra challenge','尝试拓展挑战','추가 도전하기'],'extensions','subtle')}`;
 case 'plenary':return `<div class="task-banner"><strong>A · ${esc(state.texts.messageA)}</strong><br><strong>B · ${esc(state.texts.messageB)}</strong></div><p class="question">${t(['How does one button press make your useful signal?','按一次按钮如何产生你有用的信号？','버튼을 누르면 내 유용한 신호가 어떻게 나오나요?'])}</p><p>${t(['You could start: “When I press __, my program shows __. This helps because __.”','可以这样开始：“当我按 __，程序显示 __。它能帮助别人，因为 __。”','이렇게 시작해도 돼요: “__를 누르면 프로그램이 __를 보여 줘요. 이것은 __ 때문에 도움이 돼요.”'])}</p><label class="field"><span>${t(['My explanation — write a short sentence or tell your teacher','我的解释——写简短句子或告诉老师','나의 설명 — 짧게 쓰거나 선생님께 말해요'])}</span><textarea data-text="explanation" maxlength="1000">${esc(state.texts.explanation||'')}</textarea></label>${check('explainedAloud',['I explained my signal aloud instead.','我选择口头解释信号。','대신 말로 신호를 설명했어요.'])}`;
 case 'reflection':return `<p class="question">${t(['Which helped your learning today?','今天哪种方法帮助了你的学习？','오늘 배움에 무엇이 도움이 되었나요?'])}</p>${simpleChoices('reflection',[['read',['Reading the blocks carefully','仔细阅读积木','블록을 자세히 읽기']],['test',['Testing and changing my program','测试并修改程序','프로그램을 시험하고 수정하기']],['talk',['Talking or asking for help','讨论或寻求帮助','이야기하거나 도움 요청하기']]])}${field('next',['Next time, I would like to try… — optional','下次我想尝试……——可选','다음에는 …을 해 보고 싶어요 — 선택'],state.texts.next||'')}`;
 case 'submit':return `${fileCards()}<div class="report-actions">${btn(['Save report as PDF','将报告保存为 PDF','보고서를 PDF로 저장'],'print','primary large')}<a class="button" href="https://teams.microsoft.com/" target="_blank" rel="noopener noreferrer">${t(['Open Teams ↗','打开 Teams ↗','Teams 열기 ↗'])}</a>${btn(['Download lesson backup (.json)','下载课程备份 (.json)','수업 백업 받기 (.json)'],'backup')}</div><div class="task-banner"><strong>${t(['In the print window, choose “Save as PDF”.','在打印窗口中选择“另存为 PDF”。','인쇄 창에서 “PDF로 저장”을 고르세요.'])}</strong><p>${t(['Then: Teams → your Year 6 Computing class → Classwork → the Week 9 task. Attach your PDF and .hex file. Ask your teacher if the task is not there yet.','然后：Teams → 你的六年级计算机班级 → Classwork → 第九周任务。附上 PDF 和 .hex 文件。如果还没有任务，请询问老师。','다음: Teams → 내 6학년 컴퓨팅 반 → Classwork → 9주차 과제. PDF와 .hex를 첨부해요. 과제가 아직 없으면 선생님께 물어보세요.'])}</p></div>${check('pdfSaved',['I saved my learning report as a PDF.','我已将学习报告保存为 PDF。','학습 보고서를 PDF로 저장했어요.'])}`;
 case 'finish':return `${blastroomCue()}${summary()}<div class="report-actions">${btn(['Save report as PDF','报告保存为 PDF','보고서 PDF 저장'],'print','primary')}${btn(['Download lesson backup','下载课程备份','수업 백업 받기'],'backup')}${btn(['Try a coding challenge','尝试编程挑战','코딩 도전하기'],'extensions','subtle')}</div><p class="footnote">${t(['A completed website is not the same as a completed program. Share your .hex file so your teacher can see what you made.','完成网页不等于完成程序。请提交 .hex 文件，让老师查看你的作品。','웹사이트를 끝낸 것과 프로그램을 완성한 것은 달라요. 만든 것을 선생님이 볼 수 있도록 .hex 파일을 제출해요.'])}</p>`;
 default:return '';
 }}
 function blastroomCue(){const b=L.blastroom;return `<section class="blastroom-cue" aria-labelledby="blastroomTitle"><p class="blastroom-label">${t(b.label)}</p><div class="blastroom-heading"><h3 id="blastroomTitle">${t(b.title)}</h3><a class="button primary large" href="${esc(b.url)}" target="_blank" rel="noopener noreferrer">${t(b.link)}</a></div>${steps(b.steps)}<p class="blastroom-wait">${t(b.pupil)}</p><p class="footnote">${t(b.note)}</p></section>`;}
 function testSelect(k){const option=a=>esc(a[0]+(state.lang==='zh'?' / '+a[1]:state.lang==='ko'?' / '+a[2]:''));return `<select data-test="${k}" aria-label="Button ${k} test result"><option value="">${option(['Choose result','选择结果','결과 선택'])}</option><option value="worked" ${state.tests[k]==='worked'?'selected':''}>${option(['Worked as planned','按计划工作','계획대로 작동'])}</option><option value="fix" ${state.tests[k]==='fix'?'selected':''}>${option(['Needs a change','还需要修改','수정이 더 필요'])}</option></select>`;}
 function simpleChoices(id,opts){return `<div class="choices">${opts.map(([v,a],i)=>`<button class="choice ${state.answers[id]===v?'selected':''}" data-simple="${id}" data-value="${v}" aria-pressed="${state.answers[id]===v}"><span class="letter">${i+1}</span><span>${t(a)}</span></button>`).join('')}</div>`;}
 function fileCards(){return `<div class="file-cards"><div class="file-card"><span class="file-type">PDF</span><h3>${t(['My learning report','我的学习报告','내 학습 보고서'])}</h3><p>${t(['Answers, tests and reflections. Give this to your teacher.','答案、测试和反思。交给老师。','답, 시험 기록, 돌아보기가 담겨요. 선생님께 제출해요.'])}</p></div><div class="file-card"><span class="file-type">HEX</span><h3>${t(['My real program','我真正的程序','내 실제 프로그램'])}</h3><p>${t(['Download from MakeCode. Give this to your teacher too.','从 MakeCode 下载，也交给老师。','MakeCode에서 받아요. 이것도 선생님께 제출해요.'])}</p></div><div class="file-card"><span class="file-type">JSON</span><h3>${t(['My lesson backup','我的课程备份','내 수업 백업'])}</h3><p>${t(['Keep this to restore this lesson on another computer. It is not your code.','用于在另一台电脑恢复课程，不是代码文件。','다른 컴퓨터에서 이 수업을 복원할 때 써요. 코드 파일은 아니에요.'])}</p></div></div>`;}
 function summary(){const p=M.practicalStatus(state);const items=[['Explored A and B','已探索 A 和 B','A와 B 탐색',p.explored],['Changed B','已修改 B','B 수정',p.modified],['Created and tested both signals','已制作并测试两个信号','두 신호 만들기 및 시험',p.created],['Saved the MakeCode file','已保存 MakeCode 文件','MakeCode 파일 저장',p.saved]];return `<div class="summary-list">${items.map(a=>`<div class="summary-item"><strong>${t(a.slice(0,3))}</strong><span>${t(a[3]?['You reported this done.','你已确认完成。','완료했다고 기록했어요.']:['Not yet recorded—ask for help or return to the task.','还未记录——请寻求帮助或返回任务。','아직 기록되지 않았어요. 도움을 요청하거나 활동으로 돌아가세요.'])}</span></div>`).join('')}</div>${state.skipped.length?`<div class="feedback retry">${t(['You asked for help or skipped some steps. That is recorded for your teacher.','你在一些步骤请求帮助或选择跳过，老师会看到记录。','몇 단계에서 도움을 요청하거나 건너뛰었어요. 선생님이 볼 수 있도록 기록돼요.'])}</div>`:''}`;}
 function extensionBody(){const e=L.extensions[activeExt-1],s=state.extensions[activeExt];const result=e.result==='sequence'?`<div class="split-result"><div class="result-panel"><h3>${t(['1 · Heart','1 · 爱心','1 · 하트'])}</h3><img src="assets/sim-heart.png" alt="First heart output"></div><div class="result-panel"><h3>${t(['2 · Small heart, after 1 second','2 · 1 秒后，小爱心','2 · 1초 뒤 작은 하트'])}</h3><img src="assets/sim-small-heart.png" alt="Later small heart output"></div></div>`:visual(e.result,['Result of this example','此示例的结果','이 예시의 결과'],'extension-result');return `<div class="extension-nav">${L.extensions.map(x=>btn(`${x.n} · ${plain(x.title)}`,'ext-level',activeExt===x.n?'selected':'',`data-level="${x.n}"`)).join('')}</div><div class="instruction-layout"><div class="instruction-copy">${makecodeButton()}${steps(e.steps)}<p class="footnote">${t(['Use this example to learn the blocks. Then choose your own pictures or message and test your version.','用示例认识积木，再选择自己的图案或信息，测试自己的版本。','예시로 블록을 익히고 내 그림이나 메시지를 골라 내 버전을 시험해요.'])}</p></div><div>${visual(activeExt===1?'teaching/draw-symbol.svg':e.code,e.title,activeExt===1?'annotated-guide':'code-image tall',['Example blocks to try in MakeCode','可以在 MakeCode 尝试的示例积木','MakeCode에서 해 볼 예시 블록'])}</div></div><section class="example-result"><h3>${t(['What the example does','示例会做什么','예시는 이렇게 작동해요'])}</h3>${result}</section><div class="diary"><label class="field"><span>${t(e.question)}</span><textarea data-extension-note="${activeExt}" maxlength="1000">${esc(s.note)}</textarea></label><div class="check-list"><label class="check"><input type="checkbox" data-extension-attempt="${activeExt}" ${s.attempted?'checked':''}><span>${t(['I tried this in MakeCode and tested my change.','我在 MakeCode 尝试并测试了修改。','MakeCode에서 시도하고 수정한 것을 시험했어요.'])}</span></label></div></div>${s.done?`<div class="feedback">${t(['You recorded this challenge as completed.','你已记录完成这个挑战。','이 도전을 완료했다고 기록했어요.'])}</div>`:''}`;}
 function teacherBar(){return teacher()?`<div class="teacher-bar"><strong>${t(['Teacher review · no password','教师查看 · 无密码','교사 검토 · 비밀번호 없음'])}</strong><select id="teacherJump" aria-label="Jump to lesson card">${L.cards.map((c,i)=>`<option value="${i}" ${i===state.card?'selected':''}>${i+1}. ${plain(sectionFor(c).label)} · ${plain(c.title)}</option>`).join('')}</select>${btn(['Lesson notes','教学说明','수업 안내'],'teacher-notes','quiet')}</div>`:'';}
 function lessonPage(){
  const c=L.cards[state.card],ext=activeExt?L.extensions[activeExt-1]:null,section=sectionFor(c);
  const same=L.cards.filter(x=>sectionFor(x).key===section.key),part=same.findIndex(x=>x.id===c.id)+1;
  const stage=ext?['Extension','拓展任务','추가 도전']:section.label;
  const name=state.profile.mode==='pair'&&state.profile.partner?state.profile.name+' + '+state.profile.partner:state.profile.name;
  return `<div class="shell">${header()}${teacherBar()}<div class="working-note">${esc(name)} · ${esc(state.profile.className)}${state.profile.mode==='pair'?' · '+btn(['Continue on my own','改为独立继续','혼자 이어 하기'],'alone','quiet'):''}</div>
   <div class="progress-row"><span class="stage-title">${t(stage)} · ${t(['Part','小节','부분'])} ${ext?activeExt:part} / ${ext?L.extensions.length:same.length}</span><span>${t(['Lesson step','课程步骤','수업 단계'])} ${state.card+1} / ${L.cards.length}</span></div>
   <progress max="${L.cards.length}" value="${state.card+1}" aria-label="Lesson position"></progress>
   <main id="main"><article class="lesson-card" data-card="${c.id}"><div class="card-top"><div class="card-heading-row"><span class="stage-badge">${t(stage)}</span><h2 id="cardTitle" tabindex="-1">${t(ext?ext.title:c.title)}</h2></div><p class="intro">${t(ext?ext.intro:c.intro)}</p></div><div class="card-body">${ext?extensionBody():body(c)}${hint?'<div class="feedback retry" role="status">'+t(hint)+'</div>':''}</div></article>
   <nav class="nav-row" aria-label="Lesson navigation">${btn(ext?['← Back to lesson','← 返回课程','← 수업으로']:['← Back','← 返回','← 이전'],ext?'close-ext':'back','',!ext&&state.card===0?'disabled':'')}<div class="nav-middle">${!ext&&state.card<L.cards.length-1?btn(['I need help / skip','需要帮助／跳过','도움이 필요해요 / 건너뛰기'],'skip','quiet'):''}${!ext&&state.card>=pitstopIndex()?btn(['Extension','拓展任务','추가 도전'],'extensions','quiet'):''}</div>${ext?btn(activeExt<L.extensions.length?['Save & next challenge →','保存并进入下一挑战 →','저장하고 다음 도전 →']:['Save & return to lesson →','保存并返回课程 →','저장하고 수업으로 →'],'save-ext','primary'):state.card<L.cards.length-1?btn(nextLabel(c),'next','primary'):btn(['Return to welcome','返回欢迎页','시작 화면으로'],'welcome','primary')}</nav></main>
   <div class="definition"><strong>${t(['Learning means getting better.','学习意味着不断进步。','배움은 더 나아지는 거예요.'])}</strong> ${t(['Show it by explaining, practising and improving.','通过解释、练习和改进来展示。','설명하고, 연습하고, 고치며 보여 주세요.'])}</div>${credit()}</div>`;
 }
function nextLabel(c){if(c.id==='hardware'&&state.answers.hardwareResult!=='simulator'){const step=/^[0-5]$/.test(state.answers.hardwareStep)?Number(state.answers.hardwareStep):0;if(step===0)return ['Next: plug in my board →','下一步：连接我的板子 →','다음: 내 보드 연결하기 →'];if(step<L.hardware.steps.length)return ['Next picture step: '+(step+1)+' / 5 →','下一个图片步骤：'+(step+1)+' / 5 →','다음 그림 단계: '+(step+1)+' / 5 →'];}const n=L.cards[state.card+1];if(n&&sectionFor(n).key!==sectionFor(c).key)return ['Next: '+sectionFor(n).label[0]+' →','下一步：'+sectionFor(n).label[1]+' →','다음: '+sectionFor(n).label[2]+' →'];return ({purpose:['Use this idea → plan my signals','采用这个想法 → 计划我的信号','이 생각으로 내 신호 계획하기 →'],plan:['Now make it in MakeCode →','现在到 MakeCode 制作 →','이제 MakeCode에서 만들기 →'],learning:['Next: Skills →','下一步：技能 →','다음: 기능 →'],learningSkills:['Next: Understanding →','下一步：理解 →','다음: 이해 →'],learningUnderstanding:['Choose my focus →','选择我的关注点 →','집중할 목표 고르기 →'],launch:['I have opened MakeCode →','我已打开 MakeCode →','MakeCode를 열었어요 →'],predictB:['Now test my prediction →','现在测试我的预测 →','이제 예상 시험하기 →'],change:['Now test both buttons →','现在测试两个按钮 →','이제 두 버튼 시험하기 →'],build:['Next: my own LED design (optional) →','下一步：自己的 LED 设计（可选） →','다음: 내 LED 디자인 (선택) →'],designSymbol:['Test my two signals →','测试我的两个信号 →','내 두 신호 시험하기 →'],testCreate:['Next: try a real micro:bit →','下一步：尝试真正的 micro:bit →','다음: 실제 micro:bit 시험 →'],pitstop:['Continue to plenary →','继续课堂总结 →','마무리로 →'],save:['See how to reopen next time →','看看下次如何重新打开 →','다음에 다시 여는 방법 보기 →'],reopenFile:['Prepare my report →','准备我的报告 →','보고서 준비 →'],submit:['Review my learning record →','查看我的学习记录 →','학습 기록 확인 →']})[c.id]||['Continue →','继续 →','계속 →'];}
 function requirement(){const c=L.cards[state.card];if(teacher())return null;if(c.type==='learningGoal'&&!L.learningResponses[state.answers['goal_'+c.goal]])return ['Choose how this goal feels, or use help / skip. There is no wrong choice.','选择你对目标的感觉，或使用帮助／跳过。这里没有错误选择。','목표에 대한 느낌을 고르거나 도움 / 건너뛰기를 눌러요. 틀린 선택은 없어요.'];if(c.type==='learningFocus'&&!L.learningGoals[state.answers.learningFocus])return ['Choose one goal to focus on, or use help / skip.','选择一个关注的目标，或使用帮助／跳过。','집중할 목표를 고르거나 도움 / 건너뛰기를 눌러요.'];if(c.type==='quiz'&&!state.answers[c.id])return chooseLabel;if(c.id==='launch'&&!state.openedMakecode)return ['Open MakeCode first, or choose “I need help / skip”.','请先打开 MakeCode，或选择“需要帮助／跳过”。','먼저 MakeCode를 열거나 “도움이 필요해요 / 건너뛰기”를 고르세요.'];if(c.response&&!M.hasShortResponse(state,c.response.key))return ['Add a few words about your thinking, or choose help / skip. Any language is welcome.','写几个词表达想法，或选择帮助／跳过。可以用任何语言。','생각을 짧게 적거나 도움 / 건너뛰기를 골라요. 어느 언어든 괜찮아요.'];if(c.check&&!c.optional&&!state.checks[c.check[0]])return ['Try the steps in MakeCode, then tick the box. If you are stuck, choose help / skip.','在 MakeCode 尝试步骤后勾选。如果卡住了，选择帮助／跳过。','MakeCode에서 단계를 해 보고 체크해요. 막히면 도움 / 건너뛰기를 골라요.'];if(c.id==='plan'&&(!M.hasShortResponse(state,'messageA')||!M.hasShortResponse(state,'messageB')))return ['Give A and B a short message. A few words are enough.','给 A 和 B 各写一条简短信息，几个词就够了。','A와 B의 메시지를 짧게 적어요. 몇 단어면 충분해요.'];if(c.id==='testCreate'&&(!state.tests.A||!state.tests.B))return ['Record what happened for A and B. “Needs a change” is a useful result too.','记录 A 和 B 的结果。“还需要修改”也是有用的结果。','A와 B의 결과를 기록해요. “수정 필요”도 유용한 결과예요.'];if(c.id==='pitstop'&&!state.phase)return ['Choose the phase that fits you now, or ask for help.','选择目前适合你的学习状态，或请求帮助。','지금 나에게 맞는 배움 상태를 고르거나 도움을 요청해요.'];if(c.id==='plenary'&&!M.hasShortResponse(state,'explanation')&&!state.checks.explainedAloud)return ['Write a short explanation or choose to explain aloud. You can also ask for help.','写简短解释，或选择口头解释，也可以请求帮助。','짧게 쓰거나 말로 설명했다고 체크해요. 도움을 요청해도 돼요.'];return null;}
 function render(){if(M.prepareQuizOrders(state,L.cards))persist();document.documentElement.lang='en';app.innerHTML=welcome?welcomePage():lessonPage();app.querySelector('.shell')?.classList.toggle('lesson-shell',!welcome);for(const b of app.querySelectorAll('[data-action="ext-level"]')){const n=+b.dataset.level;b.innerHTML=t(L.extensions[n-1].title.map(s=>n+' · '+s));}if(!welcome&&!activeExt&&L.cards[state.card].type==='quiz'){const body=app.querySelector('.card-body'),image=body.querySelector('.lesson-figure,.split-result');if(image){const left=document.createElement('div'),right=document.createElement('div');left.className='quiz-visual';right.className='quiz-question';let next=image.nextSibling;while(next){const moving=next;next=next.nextSibling;right.appendChild(moving);}left.appendChild(image);const feedback=right.querySelector('.feedback');body.append(left,right);if(feedback)body.append(feedback);body.classList.add('quiz-layout');}}document.title=(welcome?'Classroom Signals':(activeExt?'Extension':plain(sectionFor(L.cards[state.card]).label))+' · '+plain(activeExt?L.extensions[activeExt-1].title:L.cards[state.card].title))+' · Year 6';if(lastWelcome!==welcome)window.scrollTo(0,0);lastWelcome=welcome;document.getElementById('cardTitle')?.focus({preventScroll:true});}
 function safeName(){return ((state.profile.name||'Student')+'_'+(state.profile.className||'Year6')).replace(/[^\p{L}\p{N}._-]+/gu,'_').slice(0,100);}
 function downloadBackup(){persist();const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=safeName()+'_LessonBackup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast(['Backup downloaded. Load it on the welcome page next time.','备份已下载，下次可在欢迎页载入。','백업을 받았어요. 다음에는 시작 화면에서 불러오세요.']);}
 async function restore(file){if(!file)return;try{if(file.size>2*1024*1024)throw Error('too big');const restored=M.sanitise(JSON.parse(await file.text()));if(!restored.started)throw Error('not started');if(state.started&&!confirm('Replace this browser’s lesson record with this backup? Download your current backup first if you need it.'))return;state=restored;welcome=false;activeExt=0;hint='';persist();render();toast(['Your lesson is restored. You can continue alone if your partner is away.','课程已恢复。同伴不在时也能独立继续。','수업을 복원했어요. 짝이 없어도 혼자 이어 할 수 있어요.']);}catch(e){toast(['That file could not be loaded. Choose a Classroom Signals lesson backup (.json). Your current work is safe.','无法载入该文件。请选择 Classroom Signals 的 .json 备份。当前记录不受影响。','파일을 불러오지 못했어요. Classroom Signals의 .json 백업을 고르세요. 현재 기록은 안전해요.']);}}
 function openWork(){if(!L.starterURL||L.starterURL==='https://makecode.microbit.org/'){toast(['The starter link is being prepared. You can download and import the starter backup.','起始程序链接正在准备中，可以下载并导入备份。','시작 프로그램 링크를 준비 중이에요. 백업을 받아 가져올 수 있어요.']);return;}try{if(workTab&&!workTab.closed){workTab.focus();}else{const w=window.open('','y6_classroom_signals_makecode');if(!w){toast(['Allow the MakeCode tab, or open the starter backup from the help guide.','请允许打开 MakeCode 标签页，或按指南打开起始备份。','MakeCode 탭을 허용하거나 안내에 따라 시작 백업을 여세요.']);return;}let blank=false;try{blank=w.location.href==='about:blank';}catch(e){}if(blank)w.location.href=L.starterURL;w.focus();workTab=w;}state.openedMakecode=true;M.log(state,'open','MakeCode','Opened coding tab — not proof of completed code');persist();if(!welcome)render();}catch(e){toast(['Open MakeCode using the starter link in Help.','请使用帮助中的起始程序链接打开 MakeCode。','도움말의 시작 프로그램 링크로 MakeCode를 여세요.']);}}
 function showDialog(html){document.getElementById('viewerContent').innerHTML=html;if(!viewer.open)viewer.showModal();document.getElementById('closeViewer').focus();}
 function help(){showDialog(`<h2>${t(['Need a hand?','需要帮助？','도움이 필요하나요?'])}</h2>${steps([['Code in the MakeCode tab. The pictures on your lesson cards show you where to click.','在 MakeCode 标签页编程。课程卡片上的图片会展示点击位置。','코딩은 MakeCode 탭에서 해요. 수업 카드의 그림에서 클릭할 곳을 보여 줘요.'],['Use Back to revisit a step. Help / skip lets you continue without losing your work.','用“返回”重看步骤。帮助／跳过可以继续而不丢失记录。','이전으로 단계를 다시 보세요. 도움 / 건너뛰기로 기록을 잃지 않고 계속할 수 있어요.'],['At home, load your lesson JSON here and import your HEX in MakeCode. The Save & Share cards show the steps.','回家后，在这里载入课程 JSON，并在 MakeCode 导入 HEX。保存与分享卡片会展示步骤。','집에서는 여기서 수업 JSON을, MakeCode에서 HEX를 불러와요. 저장 및 공유 카드에서 방법을 보여 줘요.']])}${makecodeButton()}<div class="guide-links">${btn(['Continue alone','独立继续','혼자 이어 하기'],'alone')}</div><p class="footnote">${t(['A new starter is at','新的起始程序在','새 시작 프로그램:'])} <a href="${esc(L.starterURL)}" target="_blank" rel="noopener noreferrer">MakeCode starter ↗</a></p><label class="button" for="helpRestore">${t(['Load lesson backup (.json)','载入课程备份 (.json)','수업 백업 불러오기 (.json)'])}</label><input class="file-input" id="helpRestore" type="file" accept=".json">`);}
 function teacherNotes(){showDialog(`<h2>Teacher notes · 60 minutes</h2><p>0–5 Do Now; 5–10 mission and types of learning; 10–18 model IPO; 18–30 Main Task 1; 30–47 Main Task 2; 47–50 Learning Pitstop; 50–55 plenary/reflection; 55–60 save and hand in.</p><p>WAGBA: identify inputs and outputs; modify/test/save a block program; explain its useful purpose. Simulator core for all. No Python or Grove hardware is required. Ten Grove kits are available for later supervised extension, subject to compatible boards/modules/power checks.</p><p>Use the teacher selector to review any page. This is an open preview mode, not secure access control. Student progression records activity and self-reports; it does not verify the contents of an external MakeCode project. Inspect their HEX and hear their explanation.</p><p>Pair support: one pupil uses the mouse while the other reads/checks; swap during the creation task. Continuing alone never requires the partner’s answers or presence.</p><p>Do not require screenshots. Reports contain responses, plans, learner-reported tests and reflections. The real program is a separate .hex file. A Teams task has not been created by this app.</p><p>Visual placement: prediction code before results; concept imagery stays with the same A example; how-to guides at the practical action; the school pitstop after Main Task 2. See VISUAL-MAPPING.txt in the source package.</p>`);}
 function report(){const status=M.practicalStatus(state);const yn=v=>t(v?['Yes','是','예']:['Not yet','尚未','아직']);let quizRows=L.cards.filter(c=>c.type==='quiz').map(c=>{const a=state.answers[c.id],selected=c.options.find(x=>x[0]===a);return `<tr><td>${t(c.question)}</td><td>${selected?t(selected[1]):t(['No answer','未回答','답 없음'])}</td><td>${a?yn(a===c.correct):'—'}</td></tr>`;}).join('');return `<div class="report-head"><h1>${t(['Classroom Signals · Learning report','课堂信号 · 学习报告','교실 신호 · 학습 보고서'])}</h1><p><strong>${esc(state.profile.name)}</strong> · ${esc(state.profile.className)}</p><p>${t(['Working arrangement','学习方式','활동 방식'])}: ${esc(state.profile.mode)} ${esc(state.profile.partner)}${state.continuedAlone?' · '+t(['continued alone','后来独立继续','이후 혼자 이어 함']):''}</p><p>${t(['Date','日期','날짜'])}: ${esc(new Date().toLocaleDateString('en-GB',{timeZone:'Asia/Kuala_Lumpur'}))}</p><p class="report-note">${t(['This report records the pupil’s answers and self-reported practical work. The external MakeCode editor was not inspected or captured by this app. Submit the real .hex project too.','本报告记录学生的回答和自行确认的实践工作。本应用没有检查或截图外部 MakeCode 编辑器。请同时提交真正的 .hex 项目。','이 보고서는 학생의 답과 스스로 기록한 실습을 담고 있어요. 앱이 외부 MakeCode 편집기를 검사하거나 캡처한 것은 아니에요. 실제 .hex 작품도 제출하세요.'])}</p></div>${learningReport()}${writtenReport()}<section class="report-section"><h2>${t(['Practical work','实践工作','실습'])}</h2><table><tr><th>${t(['Task','任务','활동'])}</th><th>${t(['Record','记录','기록'])}</th></tr>${[['Explored A and B',status.explored],['Changed B',status.modified],['Created and tested both signals',status.created],['Saved MakeCode HEX',status.saved]].map(([s,v])=>`<tr><td>${esc(s)}</td><td>${yn(v)}</td></tr>`).join('')}</table></section><section class="report-section"><h2>${t(['My useful signal','我的实用信号','나의 유용한 신호'])}</h2><p>${t(L.purposes[state.purpose].title)}</p><table><tr><th>Button</th><th>Agreed message</th><th>Pupil’s test result</th></tr><tr><td>A</td><td>${esc(state.texts.messageA)}</td><td>${esc(state.tests.A||'Not recorded')}</td></tr><tr><td>B</td><td>${esc(state.texts.messageB)}</td><td>${esc(state.tests.B||'Not recorded')}</td></tr></table><p>First try: ${esc(state.answers.firstTry||'Not recorded')}</p><p>What I changed or checked: ${esc(state.texts.debug||'Not recorded')}</p></section><section class="report-section"><h2>${t(['Read and predict','阅读与预测','읽고 예상하기'])}</h2><table><tr><th>Question</th><th>Pupil’s latest answer</th><th>Matches example</th></tr>${quizRows}</table></section><section class="report-section"><h2>${t(['Learning pitstop and reflection','学习加油站与反思','배움 점검과 돌아보기'])}</h2><p>Phase: ${state.phase?t(L.phases[state.phase].title):'Not recorded'}</p><p>${esc(state.texts.phaseReason||'No written reason; discussion may have been oral.')}</p><p>My explanation: ${esc(state.texts.explanation||'Not recorded')}${state.checks.explainedAloud?' (pupil chose oral explanation)':''}</p><p>What helped: ${esc(state.answers.reflection||'Not recorded')}</p><p>Next time: ${esc(state.texts.next||'Not recorded')}</p></section><section class="report-section"><h2>${t(['Extra coding challenges','拓展编程挑战','추가 코딩 도전'])}</h2>${L.extensions.map(e=>`<h3>${e.n}. ${t(e.title)}</h3><p>${yn(state.extensions[e.n].done)} · ${esc(state.extensions[e.n].note||'No note recorded')}</p>`).join('')}</section><section class="report-section"><h2>${t(['Help and skipped steps','帮助与跳过的步骤','도움과 건너뛴 단계'])}</h2><p>${state.skipped.length?state.skipped.map(i=>`${i+1}. ${t(L.cards[i].title)}`).join('<br>'):t(['No steps were marked help / skip.','没有标记帮助／跳过的步骤。','도움 / 건너뛰기로 기록된 단계가 없어요.'])}</p></section><section class="report-section"><h2>${t(['Activity record','活动记录','활동 기록'])}</h2><p class="report-note">Answers may have been changed after feedback. Test records are pupil reports, not automated code checks.</p><table><tr><th>Action</th><th>Item</th><th>Record</th></tr>${state.events.map(e=>`<tr><td>${esc(e.type)}</td><td>${esc(e.key)}</td><td>${esc(e.value)}</td></tr>`).join('')}</table></section>`;}
 function printReport(){state.checks.reportRequested=true;M.log(state,'report','PDF','Opened print / save-as-PDF dialogue');persist();document.getElementById('printReport').innerHTML=report()+hardwareReport();window.print();}
 document.addEventListener('submit',e=>{if(e.target.id!=='startForm')return;e.preventDefault();const p=state.profile;if(!p.name.trim()||(!p.className.trim()&&!teacher())){const x=document.getElementById('formError');x.hidden=false;x.innerHTML=t(['Please type your name and class.','请输入姓名和班级。','이름과 반을 적어 주세요.']);return;}if(state.started&&!confirm('Start a new learner record? Download the current lesson backup first if you need to keep it.'))return;const next=M.fresh();next.profile={...p,name:p.name.trim(),className:p.className.trim()||'Teacher',originalPartner:p.partner};next.lang=state.lang;next.started=true;next.startedAt=new Date().toISOString();state=next;welcome=false;hint='';M.log(state,'start','lesson',p.mode);persist();render();});
 document.addEventListener('input',e=>{const el=e.target;if(el.dataset.profile){state.profile[el.dataset.profile]=el.value;return;}if(el.dataset.text){state.texts[el.dataset.text]=el.value;persist();}if(el.dataset.extensionNote){state.extensions[+el.dataset.extensionNote].note=el.value;persist();}});
 document.addEventListener('change',e=>{const el=e.target;if(el.dataset.setting==='lang'){state.lang=el.value;M.log(state,'language','support',el.value);persist();render();}else if(el.name==='mode'){state.profile.mode=el.value;render();}else if(el.dataset.check){state.checks[el.dataset.check]=el.checked;M.log(state,'check',el.dataset.check,el.checked);persist();}else if(el.dataset.test){state.tests[el.dataset.test]=el.value;M.log(state,'test',el.dataset.test,el.value);persist();}else if(el.dataset.text){M.log(state,'response',el.dataset.text,el.value);persist();}else if(el.dataset.extensionAttempt){state.extensions[+el.dataset.extensionAttempt].attempted=el.checked;persist();}else if(el.id==='teacherJump'&&teacher()){M.jump(state,+el.value,true);activeExt=0;hint='';persist();render();}else if(['restoreFile','helpRestore'].includes(el.id)){if(viewer.open)viewer.close();restore(el.files[0]);}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.id==='closeViewer'){viewer.close();return;}if(el.dataset.answer){state.answers[el.dataset.answer]=el.dataset.value;M.log(state,'answer',el.dataset.answer,el.dataset.value);hint='';persist();render();return;}if(el.dataset.simple){state.answers[el.dataset.simple]=el.dataset.value;M.log(state,'response',el.dataset.simple,el.dataset.value);persist();render();return;}if(el.dataset.purpose){const previous=state.purpose;state.purpose=el.dataset.purpose;const p=L.purposes[state.purpose],i=state.lang==='zh'?1:state.lang==='ko'?2:0;if(previous!==state.purpose||(!state.texts.messageA&&!state.texts.messageB)){state.texts.messageA=p.A[i];state.texts.messageB=p.B[i];}M.log(state,'purpose','signal',state.purpose);persist();render();return;}if(el.dataset.phase){state.phase=el.dataset.phase;M.log(state,'phase','pitstop',state.phase);hint='';persist();render();return;}const a=el.dataset.action;if(!a)return;switch(a){case'welcome':welcome=true;activeExt=0;render();break;case'resume':welcome=false;render();break;case'next':{if(L.cards[state.card].id==='hardware'&&state.answers.hardwareResult!=='simulator'){const n=/^[0-5]$/.test(state.answers.hardwareStep)?Number(state.answers.hardwareStep):0;if(n<L.hardware.steps.length){state.answers.hardwareStep=String(n+1);M.log(state,'guide','hardwareStep',String(n+1));persist();render();break;}}const r=requirement();if(r){hint=r;render();break;}if(L.cards[state.card].id==='purpose'&&!state.texts.messageA){const p=L.purposes[state.purpose],i=state.lang==='zh'?1:state.lang==='ko'?2:0;state.texts.messageA=p.A[i];state.texts.messageB=p.B[i];}M.log(state,'continue',L.cards[state.card].id,'completed');M.advance(state);hint='';persist();render();break;}case'back':if(state.card>0)state.card--;hint='';persist();render();break;case'skip':M.log(state,'help-skip',L.cards[state.card].id,'Pupil chose help or skip; no correctness assumed');M.advance(state,true);hint='';persist();render();break;case'backup':downloadBackup();break;case'print':printReport();break;case'makecode':openWork();break;case'help':help();break;case'route':lessonRoute();break;case'alone':M.alone(state);M.log(state,'mode','working','Continued alone');persist();if(viewer.open)viewer.close();render();toast(['You can continue on your own. Your shared work is kept.','你可以独立继续，已有共同记录会保留。','혼자 이어 할 수 있어요. 함께 한 기록은 보관돼요.']);break;case'extensions':if(state.card>=pitstopIndex()||teacher()){activeExt=1;hint='';render();}break;case'ext-level':activeExt=+el.dataset.level;hint='';render();break;case'close-ext':activeExt=0;hint='';render();break;case'save-ext':if(!state.extensions[activeExt].attempted&&!teacher()){hint=['Try this challenge in MakeCode and tick the box, or return to the lesson.','在 MakeCode 尝试后勾选，或者返回课程。','MakeCode에서 시도하고 체크하거나 수업으로 돌아가세요.'];render();break;}state.extensions[activeExt].done=state.extensions[activeExt].attempted;M.log(state,'extension',String(activeExt),state.extensions[activeExt].note||'Pupil reported testing');activeExt=activeExt<3?activeExt+1:0;hint='';persist();render();break;case'teacher-notes':teacherNotes();break;case'credits':showDialog(`<h2>Visuals and privacy</h2><p>Code blocks and simulator results were captured from the real Microsoft MakeCode editor. A pictured result is an example, not a capture of a pupil’s work. Source: <a href="https://makecode.microbit.org/" target="_blank" rel="noopener noreferrer">Microsoft MakeCode</a>.</p><p>The classroom and scenario illustrations were created with OpenAI image generation and reviewed for anatomy, setting and classroom plausibility. School Knowledge/Skills/Understanding and Learning Pitstop posters are reused, not regenerated. Real hardware photo: <a href="https://microbit.org/get-started/getting-started/introduction/" target="_blank" rel="noopener noreferrer">Micro:bit Educational Foundation</a>.</p><p>No account, password, analytics or server collection is used by this lesson. Names and responses stay in browser storage and files you choose to download. MakeCode, YouTube and Teams are separate services with their own policies. The cable demonstration is embedded from YouTube in privacy-enhanced mode; playback needs internet access. This app cannot inspect or automatically screenshot another service’s editor.</p>`);break;}});
 document.addEventListener('keydown',e=>{if(welcome||viewer.open||e.target.closest('input,textarea,select,button'))return;if(e.key==='ArrowLeft'){document.querySelector('[data-action="back"]')?.click();e.preventDefault();}if(e.key==='ArrowRight'){document.querySelector('[data-action="next"]')?.click();e.preventDefault();}});
 window.addEventListener('beforeprint',()=>{if(!document.getElementById('printReport').innerHTML)document.getElementById('printReport').innerHTML=report();});
 render();
})();
